import{_ as d,o as a,c as r,ag as e}from"./chunks/framework.CAXxHpAX.js";const c=JSON.parse('{"title":"进给量与转速","description":"","frontmatter":{},"headers":[],"relativePath":"pages/UG/UG12/rpm.md","filePath":"pages/UG/UG12/rpm.md"}'),l={name:"pages/UG/UG12/rpm.md"};function h(i,t,o,n,m,s){return a(),r("div",null,[...t[0]||(t[0]=[e('<h1 id="进给量与转速" tabindex="-1">进给量与转速 <a class="header-anchor" href="#进给量与转速" aria-label="Permalink to &quot;进给量与转速&quot;">​</a></h1><h2 id="一、核心计算公式" tabindex="-1">一、核心计算公式 <a class="header-anchor" href="#一、核心计算公式" aria-label="Permalink to &quot;一、核心计算公式&quot;">​</a></h2><h3 id="_1-主轴转速" tabindex="-1">1. 主轴转速 <a class="header-anchor" href="#_1-主轴转速" aria-label="Permalink to &quot;1. 主轴转速&quot;">​</a></h3><p>主轴转速 = 切削线速度 × 1000 ÷ (3.14 × 刀具直径)</p><p>n = Vc × 1000 ÷ (π × D)</p><ul><li>n：主轴转速 r/min</li><li>Vc：切削线速度 m/min</li><li>D：刀具直径 mm</li></ul><h3 id="_2-进给速度" tabindex="-1">2. 进给速度 <a class="header-anchor" href="#_2-进给速度" aria-label="Permalink to &quot;2. 进给速度&quot;">​</a></h3><p>每分钟进给 = 每齿进给量 × 刀具齿数 × 主轴转速</p><p>F = fz × Z × n</p><ul><li>F：每分钟进给 mm/min</li><li>fz：每齿进给量 mm/齿</li><li>Z：刀具齿数</li><li>n：主轴转速</li></ul><h2 id="二、ug软件设置步骤" tabindex="-1">二、UG软件设置步骤 <a class="header-anchor" href="#二、ug软件设置步骤" aria-label="Permalink to &quot;二、UG软件设置步骤&quot;">​</a></h2><ol><li>打开型腔铣、平面铣等加工工序</li><li>找到【进给率和速度】选项卡</li><li>勾选主轴转速，输入切削线速度，点击自动计算转速</li><li>输入每齿进给量，自动计算切削进给</li><li>分别设置：快进、逼近、切削、退刀、离开各段速度</li></ol><h2 id="三、常用材料切削线速度参考-硬质合金刀具" tabindex="-1">三、常用材料切削线速度参考（硬质合金刀具） <a class="header-anchor" href="#三、常用材料切削线速度参考-硬质合金刀具" aria-label="Permalink to &quot;三、常用材料切削线速度参考（硬质合金刀具）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>工件材料</th><th>粗加工 m/min</th><th>精加工 m/min</th></tr></thead><tbody><tr><td>45#碳钢</td><td>80~120</td><td>120~180</td></tr><tr><td>铝合金</td><td>300~800</td><td>800~1500</td></tr><tr><td>304不锈钢</td><td>60~80</td><td>80~120</td></tr><tr><td>铸铁</td><td>100~150</td><td>150~200</td></tr><tr><td>淬火硬钢</td><td>40~60</td><td>60~80</td></tr></tbody></table><h2 id="四、每齿进给量参考" tabindex="-1">四、每齿进给量参考 <a class="header-anchor" href="#四、每齿进给量参考" aria-label="Permalink to &quot;四、每齿进给量参考&quot;">​</a></h2><table tabindex="0"><thead><tr><th>刀具直径</th><th>粗加工 mm/齿</th><th>半精加工 mm/齿</th><th>精加工 mm/齿</th></tr></thead><tbody><tr><td>φ6</td><td>0.04~0.08</td><td>0.08~0.12</td><td>0.02~0.05</td></tr><tr><td>φ10</td><td>0.06~0.12</td><td>0.10~0.18</td><td>0.03~0.06</td></tr><tr><td>φ16</td><td>0.10~0.20</td><td>0.15~0.25</td><td>0.05~0.10</td></tr></tbody></table><h2 id="五、不同加工类型参数选择原则" tabindex="-1">五、不同加工类型参数选择原则 <a class="header-anchor" href="#五、不同加工类型参数选择原则" aria-label="Permalink to &quot;五、不同加工类型参数选择原则&quot;">​</a></h2><h3 id="_1-粗加工" tabindex="-1">1. 粗加工 <a class="header-anchor" href="#_1-粗加工" aria-label="Permalink to &quot;1. 粗加工&quot;">​</a></h3><p>以高效率为主，选用中低线速度、较大每齿进给，加大切深与步距，减少抬刀。</p><h3 id="_2-半精加工" tabindex="-1">2. 半精加工 <a class="header-anchor" href="#_2-半精加工" aria-label="Permalink to &quot;2. 半精加工&quot;">​</a></h3><p>转速提高20%~30%，进给降低10%~20%，保证余量均匀，减少振动。</p><h3 id="_3-精加工" tabindex="-1">3. 精加工 <a class="header-anchor" href="#_3-精加工" aria-label="Permalink to &quot;3. 精加工&quot;">​</a></h3><p>高转速、低进给、浅切削深度，提升表面粗糙度与零件精度。</p><h3 id="_4-薄壁-硬料-深槽加工" tabindex="-1">4. 薄壁/硬料/深槽加工 <a class="header-anchor" href="#_4-薄壁-硬料-深槽加工" aria-label="Permalink to &quot;4. 薄壁/硬料/深槽加工&quot;">​</a></h3><p>整体转速、进给下降30%~50%，降低切削负载，防止弹刀、崩刀、过切。</p><h2 id="六、通用设置原则" tabindex="-1">六、通用设置原则 <a class="header-anchor" href="#六、通用设置原则" aria-label="Permalink to &quot;六、通用设置原则&quot;">​</a></h2><ol><li>硬质合金刀具线速度高，高速钢刀具需降低转速50%以上。</li><li>钢件优先采用顺铣，减少刀具磨损与加工毛刺。</li><li>拐角、狭窄区域开启拐角减速，防止负载骤增崩刀。</li><li>机床刚性差、装夹不稳定时，适当降低转速和进给。</li></ol><h2 id="七、简易记忆口诀" tabindex="-1">七、简易记忆口诀 <a class="header-anchor" href="#七、简易记忆口诀" aria-label="Permalink to &quot;七、简易记忆口诀&quot;">​</a></h2><p>线速决定转速，齿距决定进给； 粗加工慢转快跑，精加工高转慢走； 硬料薄壁降参数，顺铣减速保安全。</p><h1 id="常用材料数控铣削参数对照表" tabindex="-1">常用材料数控铣削参数对照表 <a class="header-anchor" href="#常用材料数控铣削参数对照表" aria-label="Permalink to &quot;常用材料数控铣削参数对照表&quot;">​</a></h1><p>统一基准：刀具直径 D=10mm 参数包含：主轴转速S、进给F、每层下刀深度、横向步距</p><h2 id="八、高速钢刀具-hss" tabindex="-1">八、高速钢刀具 HSS <a class="header-anchor" href="#八、高速钢刀具-hss" aria-label="Permalink to &quot;八、高速钢刀具 HSS&quot;">​</a></h2><table tabindex="0"><thead><tr><th>工件材料</th><th>加工类型</th><th>主轴转速S(r/min)</th><th>进给F(mm/min)</th><th>每层下刀深度(mm)</th><th>横向步距(mm)</th></tr></thead><tbody><tr><td>45#碳钢</td><td>粗加工</td><td>800～1000</td><td>200～350</td><td>1.0～1.5</td><td>3.0～4.0</td></tr><tr><td>45#碳钢</td><td>精加工</td><td>1200～1500</td><td>120～200</td><td>0.3～0.6</td><td>1.0～2.0</td></tr><tr><td>铸铁</td><td>粗加工</td><td>900～1100</td><td>250～400</td><td>1.2～2.0</td><td>3.5～5.0</td></tr><tr><td>铸铁</td><td>精加工</td><td>1400～1800</td><td>150～220</td><td>0.3～0.8</td><td>1.5～2.5</td></tr><tr><td>7075铝合金</td><td>粗加工</td><td>4000～5000</td><td>600～800</td><td>2.5～4.0</td><td>4.0～5.5</td></tr><tr><td>7075铝合金</td><td>精加工</td><td>5000～6000</td><td>400～600</td><td>0.3～1.0</td><td>1.5～2.5</td></tr><tr><td>304不锈钢</td><td>粗加工</td><td>500～700</td><td>150～250</td><td>0.5～1.0</td><td>2.0～3.0</td></tr><tr><td>304不锈钢</td><td>精加工</td><td>700～900</td><td>100～180</td><td>0.2～0.5</td><td>0.8～1.5</td></tr><tr><td>黄铜/铜</td><td>粗加工</td><td>2500～3500</td><td>500～700</td><td>2.0～3.0</td><td>3.5～5.0</td></tr><tr><td>黄铜/铜</td><td>精加工</td><td>3500～4500</td><td>300～500</td><td>0.3～0.8</td><td>1.2～2.0</td></tr></tbody></table><h2 id="九、硬质合金刀具" tabindex="-1">九、硬质合金刀具 <a class="header-anchor" href="#九、硬质合金刀具" aria-label="Permalink to &quot;九、硬质合金刀具&quot;">​</a></h2><table tabindex="0"><thead><tr><th>工件材料</th><th>加工类型</th><th>主轴转速S(r/min)</th><th>进给F(mm/min)</th><th>每层下刀深度(mm)</th><th>横向步距(mm)</th></tr></thead><tbody><tr><td>45#碳钢</td><td>粗加工</td><td>2800～3500</td><td>800～1200</td><td>2.0～3.0</td><td>5.0～6.0</td></tr><tr><td>45#碳钢</td><td>精加工</td><td>3500～4500</td><td>500～800</td><td>0.5～1.0</td><td>2.0～3.0</td></tr><tr><td>铸铁</td><td>粗加工</td><td>3000～3800</td><td>900～1300</td><td>2.5～3.5</td><td>5.0～6.5</td></tr><tr><td>铸铁</td><td>精加工</td><td>3800～5000</td><td>600～900</td><td>0.5～1.2</td><td>2.5～3.5</td></tr><tr><td>7075铝合金</td><td>粗加工</td><td>8000～12000</td><td>1500～2500</td><td>3.0～5.0</td><td>5.0～7.0</td></tr><tr><td>7075铝合金</td><td>精加工</td><td>12000～15000</td><td>1000～1800</td><td>0.5～1.5</td><td>2.0～3.0</td></tr><tr><td>304不锈钢</td><td>粗加工</td><td>1200～1800</td><td>400～600</td><td>1.0～1.5</td><td>3.0～4.0</td></tr><tr><td>304不锈钢</td><td>精加工</td><td>1800～2500</td><td>250～400</td><td>0.3～0.8</td><td>1.0～2.0</td></tr><tr><td>淬火钢HRC50+</td><td>粗加工</td><td>800～1200</td><td>200～350</td><td>0.5～1.0</td><td>2.0～3.0</td></tr><tr><td>淬火钢HRC50+</td><td>精加工</td><td>1200～1600</td><td>120～220</td><td>0.2～0.5</td><td>0.8～1.5</td></tr></tbody></table><h2 id="十、通用选用原则" tabindex="-1">十、通用选用原则 <a class="header-anchor" href="#十、通用选用原则" aria-label="Permalink to &quot;十、通用选用原则&quot;">​</a></h2><ol><li>铝件：高转速、大进给、大切深，充足冷却防止粘刀。</li><li>普通钢件：中转速、中进给，分层切削，减少震动。</li><li>不锈钢：低转速、慢进给、小切深，防止崩刀与加工硬化。</li><li>高速钢刀具整体参数，约为合金刀具的三分之一。</li><li>封闭槽、薄壁、装夹刚性差时，所有参数降低30%使用。</li></ol>',37)])])}const u=d(l,[["render",h]]);export{c as __pageData,u as default};
